// Client-side navigation. A URL resolves to an entry point (from the static
// table, or with a route query); the entry point's module is loaded, its
// queries are started with loadEntryPoint, and the page renders through an
// EntryPointContainer. Opening a post keeps the feed and adds the dialog.
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, useTransition, startTransition } from "react";
import { EntryPointContainer, loadEntryPoint, fetchQuery } from "react-relay";
import RelayEnvironment from "RelayEnvironment";
import { RouterContext, RouteContext } from "RouterContext";
import { matchStaticRoute, entryPointResource, appPathToLocation, currentAppPath } from "SiteRoutes";
import SiteRouteQuery from "SiteRouteQuery.graphql";
import { emitStepEvent } from "Workload";
import PerfLogger from "PerfLogger";

const environmentProvider = { getEnvironment: () => RelayEnvironment };

async function resolveRoute(url) {
  const known = matchStaticRoute(url);
  if (known) {
    return known;
  }
  const data = await fetchQuery(RelayEnvironment, SiteRouteQuery, { url }).toPromise();
  const route = data?.route;
  if (!route) {
    throw new Error(`No route for ${url}`);
  }
  return { entryPoint: route.entry_point, params: { vanity: route.params?.vanity ?? null, id: route.params?.id ?? null } };
}

// A page is always built from fresh queries, also when its data is still in
// the store from an earlier visit.
function withFreshQueries(entryPoint) {
  return {
    ...entryPoint,
    getPreloadProps(params) {
      const props = entryPoint.getPreloadProps(params);
      const queries = {};
      for (const [key, query] of Object.entries(props.queries ?? {})) {
        queries[key] = { ...query, options: { ...query.options, fetchPolicy: "network-only" } };
      }
      return { ...props, queries };
    },
  };
}

async function prepare(route) {
  const entryPoint = await entryPointResource(route.entryPoint).load();
  return loadEntryPoint(environmentProvider, withFreshQueries(entryPoint.default ?? entryPoint), route.params);
}

export default function SiteRouter({ initialUrl, initialEntryPointReference, renderShell }) {
  const [state, setState] = useState(() => {
    const dialog = matchStaticRoute(initialUrl)?.dialog ?? null;
    return { url: initialUrl, pageUrl: dialog ? "/" : initialUrl, reference: initialEntryPointReference, dialog, params: {} };
  });
  const [, startNavigation] = useTransition();

  const navigate = useCallback((url, { replace = false } = {}) => {
    const instance = PerfLogger.newInstanceKey();
    PerfLogger.markerStart("navigation", instance);
    if (replace) {
      history.replaceState({ url }, "", appPathToLocation(url));
    } else {
      history.pushState({ url }, "", appPathToLocation(url));
    }
    resolveRoute(url).then(async (route) => {
      if (route.dialog) {
        setState((previous) => ({ ...previous, url, dialog: route.dialog }));
        PerfLogger.markerEnd("navigation", "dialog", instance);
        return;
      }
      const reference = await prepare(route);
      startNavigation(() => setState({ url, pageUrl: url, reference, dialog: null, params: route.params }));
      PerfLogger.markerEnd("navigation", "page", instance);
    });
  }, []);

  const closeDialog = useCallback(() => {
    history.back();
  }, []);

  // Back and forward: closing a dialog keeps the page; going back to
  // another page loads it again, as the reference rebuilds the feed from
  // fresh queries instead of restoring it.
  const stateRef = useRef(state);
  stateRef.current = state;
  useEffect(() => {
    history.scrollRestoration = "manual";
    const onPopState = () => {
      const url = currentAppPath();
      resolveRoute(url).then(async (route) => {
        if (route.dialog) {
          setState((previous) => ({ ...previous, url, dialog: route.dialog }));
          return;
        }
        if (stateRef.current.pageUrl === url) {
          setState((previous) => ({ ...previous, url, dialog: null }));
          return;
        }
        const reference = await prepare(route);
        startTransition(() => setState({ url, pageUrl: url, reference, dialog: null, params: route.params }));
      });
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  const router = useMemo(() => ({ navigate, closeDialog, url: state.url }), [navigate, closeDialog, state.url]);
  const route = useMemo(() => ({ url: state.url, params: state.params, dialog: state.dialog }), [state.url, state.params, state.dialog]);

  useEffect(() => () => state.reference?.dispose?.(), [state.reference]);

  // A new or rebuilt page starts at the top. The browser's own scroll
  // restoration would land at a different moment in each run.
  useLayoutEffect(() => {
    window.scrollTo(0, 0);
  }, [state.pageUrl]);

  useEffect(() => {
    emitStepEvent("route-committed", { url: state.url });
  }, [state.reference]);

  return (
    <RouterContext.Provider value={router}>
      <RouteContext.Provider value={route}>{renderShell(state.reference ? <EntryPointContainer entryPointReference={state.reference} props={{}} /> : null, state.dialog)}</RouteContext.Provider>
    </RouterContext.Provider>
  );
}
